CREATE TABLE IF NOT EXISTS request_types(id uuid PRIMARY KEY,name text NOT NULL,code text NOT NULL UNIQUE,description text NOT NULL DEFAULT '',icon text NOT NULL DEFAULT 'clipboard',department_id uuid REFERENCES departments(id),default_assignee_id uuid REFERENCES users(id),manager_approval boolean NOT NULL DEFAULT false,description_required boolean NOT NULL DEFAULT false,attachments_allowed boolean NOT NULL DEFAULT false,priority_allowed boolean NOT NULL DEFAULT false,active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS leave_types(id uuid PRIMARY KEY,name text NOT NULL,code text NOT NULL UNIQUE,description text NOT NULL DEFAULT '',deducts_balance boolean NOT NULL DEFAULT false,document_required boolean NOT NULL DEFAULT false,half_day boolean NOT NULL DEFAULT false,manager_approval boolean NOT NULL DEFAULT true,hr_approval boolean NOT NULL DEFAULT false,active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS requests(id uuid PRIMARY KEY,number bigint GENERATED ALWAYS AS IDENTITY UNIQUE,owner_id uuid NOT NULL REFERENCES users(id),type_id uuid NOT NULL REFERENCES request_types(id),subject text NOT NULL,description text NOT NULL DEFAULT '',priority text NOT NULL CHECK(priority IN('NORMAL','LOW','HIGH','URGENT')),department_id uuid NOT NULL REFERENCES departments(id),assignee_id uuid REFERENCES users(id),manager_id uuid REFERENCES users(id),company_id uuid REFERENCES companies(id),location_id uuid REFERENCES locations(id),owner_department_id uuid REFERENCES departments(id),status text NOT NULL CHECK(status IN('SUBMITTED','REVIEW','PENDING_MANAGER','APPROVED','REJECTED','IN_PROGRESS','COMPLETED','CANCELLED')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS leave_requests(id uuid PRIMARY KEY,number bigint GENERATED ALWAYS AS IDENTITY UNIQUE,owner_id uuid NOT NULL REFERENCES users(id),type_id uuid NOT NULL REFERENCES leave_types(id),manager_id uuid NOT NULL REFERENCES users(id),hr_approver_id uuid REFERENCES users(id),company_id uuid REFERENCES companies(id),location_id uuid REFERENCES locations(id),owner_department_id uuid REFERENCES departments(id),start_date date NOT NULL,end_date date NOT NULL,part text NOT NULL CHECK(part IN('FULL','AM','PM')),days numeric(6,1) NOT NULL CHECK(days>0),deducts_balance boolean NOT NULL,status text NOT NULL CHECK(status IN('PENDING_MANAGER','PENDING_HR','APPROVED','REJECTED','CANCELLED')),description text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(end_date>=start_date),CHECK(owner_id<>manager_id));
CREATE TABLE IF NOT EXISTS approvals(id uuid PRIMARY KEY,request_id uuid REFERENCES requests(id),leave_id uuid REFERENCES leave_requests(id),approver_id uuid NOT NULL REFERENCES users(id),stage text NOT NULL CHECK(stage IN('MANAGER','HR')),status text NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','APPROVED','REJECTED','CANCELLED')),reason text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,CHECK(num_nonnulls(request_id,leave_id)=1),CHECK((status='PENDING')=(completed_at IS NULL)));
CREATE UNIQUE INDEX IF NOT EXISTS approval_request_stage ON approvals(request_id,stage) WHERE request_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS approval_leave_stage ON approvals(leave_id,stage) WHERE leave_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS request_status_history(id uuid PRIMARY KEY,request_id uuid REFERENCES requests(id),leave_id uuid REFERENCES leave_requests(id),actor_id uuid NOT NULL REFERENCES users(id),event text NOT NULL,status text NOT NULL,note text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),CHECK(num_nonnulls(request_id,leave_id)=1));
CREATE TABLE IF NOT EXISTS leave_balance_transactions(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),type_id uuid NOT NULL REFERENCES leave_types(id),leave_id uuid UNIQUE REFERENCES leave_requests(id),days numeric(7,1) NOT NULL CHECK(days<>0),reason text NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(leave_id IS NULL OR days<0));
CREATE TABLE IF NOT EXISTS workflow_attachments(id uuid PRIMARY KEY,request_id uuid REFERENCES requests(id),leave_id uuid REFERENCES leave_requests(id),name text NOT NULL,mime text NOT NULL CHECK(mime IN('application/pdf','image/png','image/jpeg','image/webp')),data bytea NOT NULL CHECK(octet_length(data)<=200000),CHECK(num_nonnulls(request_id,leave_id)=1));
CREATE TABLE IF NOT EXISTS workflow_notifications(id uuid PRIMARY KEY,recipient_id uuid NOT NULL REFERENCES users(id),event text NOT NULL,entity_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS requests_owner_status_idx ON requests(owner_id,status,created_at DESC);
CREATE INDEX IF NOT EXISTS requests_department_status_idx ON requests(department_id,status,created_at DESC);
CREATE INDEX IF NOT EXISTS requests_assignee_idx ON requests(assignee_id,status);
CREATE INDEX IF NOT EXISTS requests_status_idx ON requests(status,created_at DESC);
CREATE INDEX IF NOT EXISTS leave_owner_status_idx ON leave_requests(owner_id,status,start_date,end_date);
CREATE INDEX IF NOT EXISTS leave_status_idx ON leave_requests(status,created_at DESC);
CREATE INDEX IF NOT EXISTS approvals_approver_status_idx ON approvals(approver_id,status,created_at DESC);
CREATE INDEX IF NOT EXISTS balance_user_type_idx ON leave_balance_transactions(user_id,type_id);
CREATE INDEX IF NOT EXISTS history_request_idx ON request_status_history(request_id,created_at);
CREATE INDEX IF NOT EXISTS history_leave_idx ON request_status_history(leave_id,created_at);
CREATE INDEX IF NOT EXISTS attachment_request_idx ON workflow_attachments(request_id);
CREATE INDEX IF NOT EXISTS attachment_leave_idx ON workflow_attachments(leave_id);
CREATE OR REPLACE FUNCTION workflow_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Workflow history is immutable' USING ERRCODE='23514'; END $$;
DROP TRIGGER IF EXISTS workflow_history_immutable ON request_status_history;
CREATE TRIGGER workflow_history_immutable BEFORE UPDATE OR DELETE ON request_status_history FOR EACH ROW EXECUTE FUNCTION workflow_immutable();
DROP TRIGGER IF EXISTS workflow_ledger_immutable ON leave_balance_transactions;
CREATE TRIGGER workflow_ledger_immutable BEFORE UPDATE OR DELETE ON leave_balance_transactions FOR EACH ROW EXECUTE FUNCTION workflow_immutable();
CREATE OR REPLACE FUNCTION workflow_approval_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' OR OLD.status<>'PENDING' OR NEW.approver_id<>OLD.approver_id OR NEW.stage<>OLD.stage OR NEW.request_id IS DISTINCT FROM OLD.request_id OR NEW.leave_id IS DISTINCT FROM OLD.leave_id THEN RAISE EXCEPTION 'Approval cannot be rewritten' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS workflow_approval_guard ON approvals;
CREATE TRIGGER workflow_approval_guard BEFORE UPDATE OR DELETE ON approvals FOR EACH ROW EXECUTE FUNCTION workflow_approval_guard();
CREATE OR REPLACE FUNCTION workflow_leave_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' OR OLD.status IN('APPROVED','REJECTED','CANCELLED') OR NEW.owner_id<>OLD.owner_id OR NEW.days<>OLD.days OR NEW.type_id<>OLD.type_id OR NEW.start_date<>OLD.start_date OR NEW.end_date<>OLD.end_date OR NEW.manager_id<>OLD.manager_id OR NEW.deducts_balance<>OLD.deducts_balance OR NEW.hr_approver_id IS DISTINCT FROM OLD.hr_approver_id THEN RAISE EXCEPTION 'Leave cannot be rewritten' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS workflow_leave_guard ON leave_requests;
CREATE TRIGGER workflow_leave_guard BEFORE UPDATE OR DELETE ON leave_requests FOR EACH ROW EXECUTE FUNCTION workflow_leave_guard();
CREATE OR REPLACE FUNCTION workflow_ledger_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.leave_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM leave_requests l WHERE l.id=NEW.leave_id AND l.status='APPROVED' AND l.deducts_balance AND l.owner_id=NEW.user_id AND l.type_id=NEW.type_id AND NEW.days=-l.days) THEN RAISE EXCEPTION 'Invalid leave debit' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS workflow_ledger_guard ON leave_balance_transactions;
CREATE TRIGGER workflow_ledger_guard BEFORE INSERT ON leave_balance_transactions FOR EACH ROW EXECUTE FUNCTION workflow_ledger_guard();
INSERT INTO request_types(id,name,code,active) SELECT md5('request-type-'||code)::uuid,name,code,false FROM (VALUES('BT Destek','IT_SUPPORT'),('Donanım Talebi','HARDWARE'),('Erişim Yetkisi','ACCESS'),('İK Talebi','HR'),('Personel Belgesi','DOCUMENT'),('Satın Alma Talebi','PURCHASE'),('İdari İşler','OFFICE'),('Diğer','OTHER')) v(name,code) ON CONFLICT DO NOTHING;
INSERT INTO leave_types(id,name,code,deducts_balance,half_day) SELECT md5('leave-type-'||code)::uuid,name,code,code='ANNUAL',true FROM (VALUES('Yıllık İzin','ANNUAL'),('Mazeret İzni','EXCUSE'),('Ücretsiz İzin','UNPAID'),('Hastalık İzni','SICK'),('Evlilik İzni','MARRIAGE'),('Doğum İzni','MATERNITY'),('Babalık İzni','PATERNITY'),('Vefat İzni','BEREAVEMENT'),('Diğer','OTHER')) v(name,code) ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION workflow_leave_balance_consistent() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF EXISTS(SELECT 1 FROM leave_requests l WHERE l.id=NEW.id AND l.status='APPROVED' AND l.deducts_balance AND NOT EXISTS(SELECT 1 FROM leave_balance_transactions b WHERE b.leave_id=l.id AND b.days=-l.days)) THEN RAISE EXCEPTION 'Approved leave requires exactly one debit' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS workflow_leave_balance_consistent ON leave_requests;
CREATE CONSTRAINT TRIGGER workflow_leave_balance_consistent AFTER INSERT OR UPDATE ON leave_requests DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION workflow_leave_balance_consistent();
